using ModuleLoadFn = CUresult (*)(CUmodule*, const void*);
using GetFuncFn = CUresult (*)(CUfunction*, CUmodule, const char*);
using SetAttrFn = CUresult (*)(CUfunction, CUfunction_attribute, int);
using LaunchFn = CUresult (*)(
    CUfunction, unsigned, unsigned, unsigned, unsigned, unsigned, unsigned, unsigned, CUstream, void**, void**);
using EncodeMapFn = CUresult (*)(
    CUtensorMap*,
    CUtensorMapDataType,
    cuuint32_t,
    void*,
    const cuuint64_t*,
    const cuuint64_t*,
    const cuuint32_t*,
    const cuuint32_t*,
    CUtensorMapInterleave,
    CUtensorMapSwizzle,
    CUtensorMapL2promotion,
    CUtensorMapFloatOOBfill);

struct CuteWs64Image {
  CUfunction fn = nullptr;
  CUfunction fn_red = nullptr;
  LaunchFn launch = nullptr;
  EncodeMapFn encode = nullptr;

  CuteWs64Image() {
    void* h = dlopen("libcuda.so.1", RTLD_NOW | RTLD_GLOBAL);
    if (h == nullptr) {
      printf("cute_ws64 e3m4 gemm: cannot dlopen libcuda.so.1\n");
      return;
    }
    auto load = reinterpret_cast<ModuleLoadFn>(dlsym(h, "cuModuleLoadData"));
    auto getf = reinterpret_cast<GetFuncFn>(dlsym(h, "cuModuleGetFunction"));
    auto setattr = reinterpret_cast<SetAttrFn>(dlsym(h, "cuFuncSetAttribute"));
    launch = reinterpret_cast<LaunchFn>(dlsym(h, "cuLaunchKernel"));
    encode = reinterpret_cast<EncodeMapFn>(dlsym(h, "cuTensorMapEncodeTiled"));
    if (load == nullptr || getf == nullptr || setattr == nullptr || launch == nullptr || encode == nullptr) {
      printf("cute_ws64 e3m4 gemm: driver entry points missing\n");
      return;
    }
    CUmodule mod = nullptr;
    if (load(&mod, kCuteWs64Cubin) != CUDA_SUCCESS) {
      printf("cute_ws64 e3m4 gemm: cuModuleLoadData failed\n");
      return;
    }
    if (getf(&fn, mod, "cute_ws_64x64") != CUDA_SUCCESS) {
      printf("cute_ws64 e3m4 gemm: entry missing\n");
      fn = nullptr;
      return;
    }
    getf(&fn_red, mod, "cute_ws_64x64_sk_reduce");
    if (setattr(fn, CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, e3m4_cute_ws64::SMEM_BYTES) != CUDA_SUCCESS) {
      printf("cute_ws64 e3m4 gemm: smem %d bytes unavailable\n", e3m4_cute_ws64::SMEM_BYTES);
      fn = nullptr;
    }
  }
};

CuteWs64Image& cute_ws64_image() {
  static CuteWs64Image img;
  return img;
}

}  // namespace

struct Sm120Fp8E3m4GemmCuteWs64 {
  // out[M,N] bf16 = A[M,K](e4m3) @ B[N,K](e3m4)^T with 64x64 scales;
  // a_s fp32 [M, K/64], w_s fp32 [ceil(N/64), K/64]. sk>1: K-split through
  // the caller-owned fp32 partial [sk,M,N].
  static void
  run(const tvm::ffi::TensorView out,
      const tvm::ffi::TensorView mat_a,
      const tvm::ffi::TensorView mat_b,
      const tvm::ffi::TensorView scales_a,
      const tvm::ffi::TensorView scales_b,
      const tvm::ffi::TensorView part,
      int64_t sk) {
    using namespace host;
    auto device = SymbolicDevice{};
    device.set_options<kDLCUDA>();
    const int M = static_cast<int>(mat_a.shape()[0]);
    const int K = static_cast<int>(mat_a.shape()[1]);
    const int N = static_cast<int>(mat_b.shape()[0]);
    TensorMatcher({M, K}).with_dtype<fp8_e4m3_t>().verify(mat_a);
    TensorMatcher({N, K}).verify(mat_b);
    TensorMatcher({M, (K + 63) / 64}).with_dtype<fp32_t>().with_device(device).verify(scales_a);
    TensorMatcher({(N + 63) / 64, (K + 63) / 64}).with_dtype<fp32_t>().with_device(device).verify(scales_b);
    TensorMatcher({M, N}).with_dtype<bf16_t>().with_device(device).verify(out);

    host::RuntimeCheck(K % 64 == 0, "cute_ws64 e3m4 gemm needs K % 64 == 0, got ", K);
    host::RuntimeCheck(N % 8 == 0, "cute_ws64 e3m4 gemm needs N % 8 == 0, got ", N);
    const int nk = (K + 127) / 128;
    host::RuntimeCheck(sk >= 1 && sk <= nk, "cute_ws64 sk out of range: ", static_cast<int>(sk), " > nk=", nk);
    const int64_t pn = static_cast<int64_t>(sk) * M * N;
    if (sk > 1) {
      host::RuntimeCheck(fn_red_ok(), "cute_ws64 reduce entry missing");
      TensorMatcher({pn}).with_dtype<fp32_t>().with_device(device).verify(part);
    }

    auto& img = cute_ws64_image();
    host::RuntimeCheck(img.fn != nullptr, "cute_ws64 image unavailable");

    e3m4_cute_ws64::Params params = e3m4_cute_ws64::make_params(
        mat_a.data_ptr(),
        K,
        mat_b.data_ptr(),
        K,
        static_cast<float*>(scales_a.data_ptr()),
        static_cast<float*>(scales_b.data_ptr()),
        M,
        N,
        K);

    CUtensorMap tm_c;
    const cuuint64_t gd[2] = {static_cast<cuuint64_t>(N), static_cast<cuuint64_t>(M)};
    const cuuint64_t gs[1] = {static_cast<cuuint64_t>(N) * 2};
    const cuuint32_t bx[2] = {64, 16};
    const cuuint32_t es[2] = {1, 1};
    CUresult rc = img.encode(
        &tm_c,
        CU_TENSOR_MAP_DATA_TYPE_UINT16,
        2,
        out.data_ptr(),
        gd,
        gs,
        bx,
        es,
        CU_TENSOR_MAP_INTERLEAVE_NONE,
        CU_TENSOR_MAP_SWIZZLE_128B,
        CU_TENSOR_MAP_L2_PROMOTION_L2_128B,
        CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
    host::RuntimeCheck(rc == CUDA_SUCCESS, "cute_ws64 tensormap encode failed: ", static_cast<int>(rc));

    void* d_ptr = out.data_ptr();
    void* p_ptr = sk > 1 ? part.data_ptr() : nullptr;
    int m = M, n = N, k = K, s = static_cast<int>(sk);
    void* kernel_params[] = {&params, &tm_c, &d_ptr, &m, &n, &k, &p_ptr, &s};
    const unsigned mtiles = static_cast<unsigned>((M + 127) / 128);
    const unsigned ntiles = static_cast<unsigned>((N + 127) / 128);
    auto stream = host::LaunchKernel::resolve_device(device.unwrap());
    rc = img.launch(
        img.fn,
        mtiles * ntiles,
        static_cast<unsigned>(sk),
        1,
        e3m4_cute_ws64::NUM_THREADS,
        1,
        1,
        e3m4_cute_ws64::SMEM_BYTES,
        static_cast<CUstream>(stream),
        kernel_params,
        nullptr);
    host::RuntimeCheck(rc == CUDA_SUCCESS, "cute_ws64 gemm launch failed: ", static_cast<int>(rc));
    if (sk > 1) {
      // reduce kernel: 2 outputs per thread over M*N (partials sized [sk,M,N]).
      const unsigned red = static_cast<unsigned>((static_cast<int64_t>(M) * N + 511) / 512);
      void* kr_p[] = {&p_ptr, &d_ptr, &m, &n, &s};
      rc = img.launch(img.fn_red, red, 1, 1, 256, 1, 1, 0, static_cast<CUstream>(stream), kr_p, nullptr);
      host::RuntimeCheck(rc == CUDA_SUCCESS, "cute_ws64 reduce launch failed: ", static_cast<int>(rc));
    }
  }

 private:
  static bool fn_red_ok() {
    return cute_ws64_image().fn_red != nullptr;
  }
};

}  // namespace sglang
